CREATE TABLE public.rab_approval_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rab_id uuid NOT NULL REFERENCES public.stock_opname_projects(id) ON DELETE CASCADE, file_name text NOT NULL CHECK (lower(file_name) LIKE '%.pdf'), file_path text NOT NULL UNIQUE, content_type text NOT NULL CHECK (content_type='application/pdf'), file_size bigint NOT NULL CHECK (file_size>0 AND file_size<=20971520), created_at timestamptz NOT NULL DEFAULT now(), CHECK (file_path LIKE 'rab-approved/' || rab_id::text || '/%.pdf'));
GRANT SELECT,INSERT,DELETE ON public.rab_approval_documents TO authenticated;
GRANT ALL ON public.rab_approval_documents TO service_role;
ALTER TABLE public.rab_approval_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Stock roles manage signed RAB metadata" ON public.rab_approval_documents FOR ALL TO authenticated USING (public.has_role(auth.uid(),'internal_audit') OR public.has_role(auth.uid(),'purchasing')) WITH CHECK (public.has_role(auth.uid(),'internal_audit') OR public.has_role(auth.uid(),'purchasing'));
CREATE POLICY "Stock roles upload signed RAB files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='stock-opname-documents' AND (storage.foldername(name))[1]='rab-approved' AND lower(storage.extension(name))='pdf' AND (public.has_role(auth.uid(),'internal_audit') OR public.has_role(auth.uid(),'purchasing')) AND EXISTS(SELECT 1 FROM public.stock_opname_projects p WHERE p.id::text=(storage.foldername(name))[2]));